y_location": {"id": "pmh:oai:www.ideals.illinois.edu:2142/102507", "doi": null, "is_oa": true, "landing_page_url": "https://hdl.handle.net/2142/102507", "pdf_url": "https://www.ideals.illinois.edu/items/109525/bitstreams/358189/data.pdf", "source": {"id": "https://openalex.org/S4306401358", "display_name": "Illinois Digital Environment for Access to Learning and Scholarship (University of Illinois at Urbana-Champaign)", "issn_l": null, "issn": null, "is_oa": false, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/I2801919071", "host_organization_name": "University of Illinois System", "host_organization_lineage": ["https://openalex.org/I2801919071"], "host_organization_lineage_names": [], "type": "repository"}, "license": null, "license_id": null, "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": null, "raw_type": "text"}, "abstract": "We investigated and implemented two computational creativity applications in generating engineering processes and building material designs respectively. To synthesize engineering processes, we developed a full system that generates engaging Rube Goldberg Machine designs. We first describe the use of case-based reasoning (CBR) and an existing knowledge base to yield a combinatorial design space for experiments. We then apply automated planning techniques to generate experiment procedures. We further use functional modeling to represent the experiment devices and demonstrate how that representation enables the planner to generate a valid Rube Goldberg Machine. Finally, a semantic similarity metric is proposed to evaluate the quality of a generated chain of experiments. To discover concrete formulas as building materials with desired properties, we use a conditional variational autoencoder (CVAE), a type of semisupervised generative model. Our model is trained using open data from the UCI Machine Learning Repository joined with environmental impact data computed using a web-based tool. We demonstrate that the CVAE can design concrete formulas with lower emissions and natural resource usage while meeting design requirements. To ensure fair comparison between extant and generated formulas, we also train regression models to predict the environmental impacts and strength of discovered formulas. With these results, a construction engineer may create a formula that meets structural needs and best addresses local environmental concerns."}]", "excerpt_truncated": true, "source_sha256": "379be2d20672c19576ad3a8a8a311c8045e13ccdabec7659cb3a46b658d584e2", "verification_required": true, "topic_domain": "unassigned_problem", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["openalex:W30239163"], "source_candidates": ["https://kar.kent.ac.uk/42388/1/Jordanous%252C_Anna_Katerina.pdf", "https://www.ideals.illinois.edu/items/109525/bitstreams/358189/data.pdf"], "source_candidate_identities": {}}
